<script setup>
import {knowledgeRows,knowledgeExcerpt,completeKnowledgeCards} from '../knowledgeSummaries.js';
import KnowledgeEvidence from "./KnowledgeEvidence.vue";
import {computed,ref,watch,onMounted,onBeforeUnmount,nextTick,inject} from 'vue';
import {routerKey} from 'vue-router';
import {api} from '../api.js';
import {currentUser,getToken} from '../auth.js';
import {refreshSessionIdentity} from '../sessionIdentity.js';
import {knowledgeScope,createKnowledgeRequestGate,toKnowledgeEditor,fromKnowledgeEditor,cardStates,cardKinds,cardKindLabel} from '../knowledgeBaseAccess.js';
import {collectionCapabilities,stableOperation} from '../knowledgeCollection.js';
import {useLiveRefresh} from '../useLiveRefresh.js';
import KnowledgeCardEditor from './KnowledgeCardEditor.vue';
import KnowledgeCardContent from './KnowledgeCardContent.vue';
import HelpHint from './HelpHint.vue';
const caps=computed(()=>collectionCapabilities(currentUser.value?.permissions)),identity=computed(()=>knowledgeScope(currentUser.value,getToken()));
const rows=ref([]),total=ref(0),offset=ref(0),query=ref(''),appliedQuery=ref(''),status=ref(''),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const draft=ref(null),baseline=ref(''),history=ref([]),version=ref(0),viewer=ref(null),selected=ref(new Set()),sharing=ref(null),editorDialog=ref(null),historyDialog=ref(null),shareDialog=ref(null);
const supportsExpression=ref(false);
const intent=ref(null),shareIntent=ref(null),gate=createKnowledgeRequestGate(),actions=createKnowledgeRequestGate();let disposed=false;
const dirty=computed(()=>!!draft.value&&JSON.stringify(draft.value)!==baseline.value);
const historyCard=computed(()=>history.value.find(c=>c.revision===Number(version.value))||history.value[0]);
const router=inject(routerKey,null);let removeGuard;
function allowLeaving(){return !busy.value&&(!dirty.value||confirm('知识卡有未保存修改，确定放弃吗？'));}
defineExpose({allowLeaving});
function beforeUnload(e){if(dirty.value||busy.value){e.preventDefault();e.returnValue='';}}
function clear(){supportsExpression.value=false;query.value='';appliedQuery.value='';status.value='';offset.value=0;gate.invalidate();actions.invalidate();rows.value=[];total.value=0;draft.value=null;history.value=[];viewer.value=null;sharing.value=null;selected.value=new Set();loading.value=false;busy.value=false;error.value='';notice.value='';intent.value=null;shareIntent.value=null;}
watch(identity,()=>{clear();if(caps.value.view)load();},{flush:'sync'});
async function load(background=false){if(!caps.value.view||disposed||background&&(loading.value||busy.value||draft.value||viewer.value||sharing.value))return;const ticket=gate.start(identity.value);if(!background){loading.value=true;error.value='';}try{const d=await api.privateKnowledge({q:appliedQuery.value,status:status.value,limit:20,offset:offset.value,view:"summary"});if(!disposed&&gate.accepts(ticket,identity.value)){supportsExpression.value=d.supports_expression===true;rows.value=knowledgeRows(d);total.value=d.total||0;error.value='';selected.value=new Set([...selected.value].filter(id=>rows.value.some(c=>c.id===id)));}}catch(e){if(!disposed&&gate.accepts(ticket,identity.value))fail(e);}finally{if(!disposed&&gate.accepts(ticket,identity.value))loading.value=false;}}
function fail(e){if([401,403].includes(e.status)){clear();refreshSessionIdentity().catch(()=>{});}error.value=e.message;}
async function openEditor(card=null){
 if(!caps.value.manage||!allowLeaving())return;
 if(!card){draft.value=toKnowledgeEditor();baseline.value=JSON.stringify(draft.value);intent.value=null;error.value='';return;}
 const ticket=actions.start(identity.value);busy.value=true;error.value='';
 try{const [full]=await completeKnowledgeCards([card],api.privateKnowledgeCard,()=>!disposed&&actions.accepts(ticket,identity.value)&&caps.value.manage);if(disposed||!actions.accepts(ticket,identity.value)||!caps.value.manage)return;draft.value=toKnowledgeEditor(full);baseline.value=JSON.stringify(draft.value);intent.value=null;}
 catch(e){if(!disposed&&actions.accepts(ticket,identity.value))fail(e);}
 finally{if(!disposed&&actions.accepts(ticket,identity.value))busy.value=false;}
}
function closeEditor(){if(allowLeaving()){draft.value=null;error.value='';}}
async function save(state,existing=null){if(!caps.value.manage||busy.value||!draft.value&&!existing)return;const card=existing?JSON.parse(JSON.stringify(existing)):fromKnowledgeEditor(draft.value);card.status=state;const payload={cards:[card]},key=stableOperation(intent,'private-save',payload),ticket=actions.start(identity.value);busy.value=true;error.value='';try{await refreshSessionIdentity();if(disposed||!actions.accepts(ticket,identity.value)||!caps.value.manage)return;const d=await api.savePrivateKnowledge({...payload,key});if(disposed||!actions.accepts(ticket,identity.value))return;if(d.cards?.length!==1||!d.cards[0].id)throw new Error('未收到保存结果，请保留内容并重试。');if(card.content?.expression&&((d.cards[0].content?.expression?.instructions||'')!==(card.content.expression.instructions||'')||(d.cards[0].content?.expression?.explanation_note||'')!==(card.content.expression.explanation_note||'')))throw new Error('服务未保留表达要求，请保留编辑并更新后端后重试。');draft.value=null;notice.value=state==='active'?'知识卡已保存并启用；勾选后可用于知识库工作流。':'已保存知识卡';await load();}catch(e){if(!disposed&&actions.accepts(ticket,identity.value))fail(e);}finally{if(!disposed&&actions.accepts(ticket,identity.value))busy.value=false;}}
async function transition(card,state){
 if(busy.value||!caps.value.manage)return;if(state==='archived'&&!confirm('归档后停止新任务采用，历史任务保留。确定归档吗？'))return;
 const ticket=actions.start(identity.value);busy.value=true;error.value='';
 try{const [full]=await completeKnowledgeCards([card],api.privateKnowledgeCard,()=>!disposed&&actions.accepts(ticket,identity.value)&&caps.value.manage);if(disposed||!actions.accepts(ticket,identity.value)||!caps.value.manage)return;busy.value=false;intent.value=null;await save(state,full);}
 catch(e){if(!disposed&&actions.accepts(ticket,identity.value))fail(e);}
 finally{if(!disposed&&actions.accepts(ticket,identity.value))busy.value=false;}
}
async function choose(card,value){if(busy.value||!caps.value.use)return;const previous=!!card.selected;card.selected=value;const ticket=actions.start(identity.value);busy.value=true;error.value='';try{await api.chooseKnowledgeCard({scope:'private',id:card.id,selected:value});if(!disposed&&actions.accepts(ticket,identity.value))card.selected=value;}catch(e){if(!disposed&&actions.accepts(ticket,identity.value)){card.selected=previous;fail(e);}}finally{if(!disposed&&actions.accepts(ticket,identity.value))busy.value=false;}}
async function showHistory(card){const ticket=actions.start(identity.value);error.value='';try{const d=await api.privateKnowledgeHistory(card.id);if(!disposed&&actions.accepts(ticket,identity.value)){history.value=d.versions||[];version.value=history.value[0]?.revision||0;viewer.value=card.id;}}catch(e){if(!disposed&&actions.accepts(ticket,identity.value))fail(e);}}
function toggle(card,checked){const ids=new Set(selected.value);if(checked)ids.add(card.id);else ids.delete(card.id);selected.value=ids;}
async function previewShare(cards){
 if(!caps.value.submit||busy.value||!cards.length)return;
 const ticket=actions.start(identity.value);busy.value=true;error.value='';
 try{const full=await completeKnowledgeCards(cards,api.privateKnowledgeCard,()=>!disposed&&actions.accepts(ticket,identity.value)&&caps.value.submit);if(disposed||!actions.accepts(ticket,identity.value)||!caps.value.submit)return;sharing.value=full;shareIntent.value=null;}
 catch(e){if(!disposed&&actions.accepts(ticket,identity.value))fail(e);}
 finally{if(!disposed&&actions.accepts(ticket,identity.value))busy.value=false;}
}
async function submitShare(){if(!sharing.value||busy.value||!caps.value.submit)return;const payload={cards:sharing.value.map(c=>({id:c.id,revision:c.revision}))},key=stableOperation(shareIntent,'share',payload),ticket=actions.start(identity.value);busy.value=true;error.value='';try{await refreshSessionIdentity();if(disposed||!actions.accepts(ticket,identity.value)||!caps.value.submit)return;const d=await api.submitKnowledgeCards({...payload,key});if(!disposed&&actions.accepts(ticket,identity.value)){if(d.submissions?.length!==payload.cards.length)throw new Error('申请结果未确认，请重试核对。');sharing.value=null;selected.value=new Set();notice.value=`已核对 ${d.submissions.length} 张申请，可在“我的申请”查看结果。`;}}catch(e){if(!disposed&&actions.accepts(ticket,identity.value))fail(e);}finally{if(!disposed&&actions.accepts(ticket,identity.value))busy.value=false;}}
watch([draft,viewer,sharing],async()=>{await nextTick();if(disposed)return;if(draft.value&&!editorDialog.value?.open)editorDialog.value?.showModal();if(viewer.value&&!historyDialog.value?.open)historyDialog.value?.showModal();if(sharing.value&&!shareDialog.value?.open)shareDialog.value?.showModal();});
useLiveRefresh(async()=>{if(!caps.value.view||busy.value)return;await refreshSessionIdentity().catch(()=>{});if(caps.value.view&&!draft.value&&!viewer.value&&!sharing.value)await load(true);});
onMounted(()=>{load();window.addEventListener('beforeunload',beforeUnload);if(router)removeGuard=router.beforeEach(allowLeaving);});
onBeforeUnmount(()=>{disposed=true;clear();removeGuard?.();window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template><section v-if="caps.view" class="panel private-cards"><div class="collection-heading"><div class="ui-help-heading"><h2>个人知识卡</h2><HelpHint label="个人知识卡说明">只有本人可见。自用无需审核；共享通过后生成独立公共副本。启用并勾选后，在知识库工作流按考点匹配，直接生成保持原行为。</HelpHint></div><button v-if="caps.manage" class="primary-button" :disabled="busy" @click="openEditor()">新增知识卡</button></div><div class="collection-toolbar"><input v-model="query" aria-label="搜索个人知识卡" placeholder="搜索标题" @keydown.enter="offset=0;appliedQuery=query;load()"/><select v-model="status" aria-label="个人知识卡状态" @change="offset=0;load()"><option value="">全部状态</option><option v-for="(label,key) in cardStates" :key="key" :value="key">{{label}}</option></select><button class="ghost-button" :disabled="loading" @click="offset=0;appliedQuery=query;load()">查询</button><button v-if="caps.submit" class="ghost-button" :disabled="busy||!selected.size" @click="previewShare(rows.filter(c=>selected.has(c.id)))">提交所选共享审核（{{selected.size}}）</button></div><p v-if="error" class="collection-error" role="alert">{{error}}</p><p v-if="notice" class="collection-success" role="status">{{notice}}</p><p v-if="loading" role="status">加载中…</p><p v-else-if="!rows.length" class="collection-empty">暂无个人知识卡</p><article v-for="card in rows" :key="card.id" class="private-knowledge-card"><div class="collection-heading"><label v-if="caps.submit&&card.status!=='archived'" class="collection-check"><input type="checkbox" :aria-label="`选择共享 ${card.title}`" :checked="selected.has(card.id)" @change="toggle(card,$event.target.checked)"/>{{card.title}}</label><strong v-else>{{card.title}}</strong><span>{{cardKindLabel(card)}} · {{cardStates[card.status]}} · v{{card.revision}}</span></div><p class="collection-meta">{{card.knowledge_points.map(p=>p.topic).join('、')||'尚未关联考点'}}</p><p class="collection-excerpt">{{knowledgeExcerpt(card)||'查看内容与历史'}}</p><div class="collection-actions"><label v-if="caps.use" class="collection-check"><input type="checkbox" :aria-label="`用于出题 ${card.title}`" :disabled="busy||card.status!=='active'&&!card.selected" :checked="card.selected" @change="choose(card,$event.target.checked)"/>用于我的出题</label><button class="ghost-button" :disabled="busy" @click="showHistory(card)">查看与历史</button><template v-if="caps.manage"><button class="ghost-button" :disabled="busy" @click="openEditor(card)">编辑</button><button v-if="card.status==='active'" class="ghost-button" :disabled="busy" @click="transition(card,'draft')">停用</button><button v-else-if="card.status==='draft'" class="ghost-button" :disabled="busy" @click="transition(card,'active')">启用</button><button v-else class="ghost-button" :disabled="busy" @click="transition(card,'draft')">恢复为草稿</button><button v-if="card.status!=='archived'" class="text-button" :disabled="busy" @click="transition(card,'archived')">归档</button></template><button v-if="caps.submit&&card.status!=='archived'" class="ghost-button" :disabled="busy" @click="previewShare([card])">申请共享</button></div></article><div class="collection-actions collection-pager"><span>共 {{total}} 张</span><button class="ghost-button" :disabled="!offset||loading" @click="offset=Math.max(0,offset-20);load()">上一页</button><button class="ghost-button" :disabled="offset+20>=total||loading" @click="offset+=20;load()">下一页</button></div>
<Teleport to="body"><dialog v-if="draft&&caps.manage" ref="editorDialog" class="collection-dialog" @cancel.prevent="closeEditor"><form @submit.prevent="save('draft')"><div class="collection-heading"><h2>{{draft.id?'编辑':'新增'}}个人知识卡</h2><button type="button" class="ghost-button" aria-label="关闭个人卡编辑" :disabled="busy" @click="closeEditor">×</button></div><KnowledgeCardEditor :model-value="draft" :disabled="busy" :allow-expression="supportsExpression"/><p v-if="error" class="collection-error" role="alert">{{error}}</p><div class="collection-actions"><button type="button" class="ghost-button" :disabled="busy" @click="closeEditor">取消</button><button class="ghost-button" :disabled="busy">保存草稿</button><button type="button" class="primary-button" :disabled="busy" @click="save('active')">保存并启用</button></div></form></dialog><dialog v-if="viewer" ref="historyDialog" class="collection-dialog" @cancel.prevent="viewer=null"><div class="collection-heading"><h2>知识卡与历史</h2><button class="ghost-button" aria-label="关闭个人卡详情" @click="viewer=null">×</button></div><label>查看版本<select v-model="version" aria-label="个人知识卡历史版本"><option v-for="card in history" :key="card.revision" :value="card.revision">v{{card.revision}} · {{cardStates[card.status]}}</option></select></label><KnowledgeCardContent v-if="historyCard" :card="historyCard" :show-note="true"/></dialog><dialog v-if="sharing&&caps.submit" ref="shareDialog" class="collection-dialog" @cancel.prevent="!busy&&(sharing=null)"><h2>核对共享申请</h2><p>以下正文、来源、考点和所选修改片段会提供给审核人。通过后仅知识卡正文、来源及考点进入共享库；私人维护备注和未选条目不提交。</p><article v-for="card in sharing" :key="card.id"><h3>{{card.title}}</h3><KnowledgeCardContent :card="card"/><KnowledgeEvidence :source="card.origin"/></article><p v-if="error" class="collection-error" role="alert">{{error}}</p><div class="collection-actions"><button class="ghost-button" :disabled="busy" @click="sharing=null">取消</button><button class="primary-button" :disabled="busy" @click="submitShare">确认提交（{{sharing.length}} 张）</button></div></dialog></Teleport></section><section v-else class="panel">当前身份没有个人知识卡查看权限。</section></template>
